def twoSum(nums, target):
    # 核心思路：用哈希表记录已遍历元素的值到下标的映射
    # 对每个元素 v，只需查表判断 target - v 是否出现过
    # 先查再存，避免同一个元素与自己配对
    # 时间复杂度 O(n)，空间复杂度 O(n)
    d = {}
    for i, v in enumerate(nums):
        if target - v in d:
            return [d[target - v], i]
        d[v] = i
    return []

