class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        // 核心思路：滑动窗口，右指针扩展、左指针收缩
        // last 记录字符最近一次出现的位置，重复时更新左边界
        // l 只增不减，保证窗口内始终无重复字符
        // 时间复杂度 O(n)，空间复杂度 O(字符集大小)
        unordered_map<char, int> last;
        int l = 0, ans = 0;
        for (int r = 0; r < (int)s.size(); r++) {
            if (last.count(s[r])) l = max(l, last[s[r]] + 1);
            last[s[r]] = r;
            ans = max(ans, r - l + 1);
        }
        return ans;
    }
};

