def findMedianSortedArrays(nums1, nums2):
    # 核心思路：对较短的数组二分切分点 i，使左半元素数恰为 (m+n+1)//2，
    # 且左半最大值不超过右半最小值，从而直接得出中位数。
    # 易错点：i、j 的边界情况要单独取值；奇数长度直接返回左半最大值。
    # 时间复杂度 O(log min(m,n))，空间复杂度 O(1)。
    A, B = nums1, nums2
    if len(A) > len(B):
        A, B = B, A
    m, n = len(A), len(B)
    lo, hi = 0, m
    total_left = (m + n + 1) // 2
    while lo <= hi:
        i = (lo + hi) // 2
        j = total_left - i
        if i < m and A[i] < B[j - 1]:
            lo = i + 1
        elif i > 0 and A[i - 1] > B[j]:
            hi = i - 1
        else:
            if i == 0:
                max_left = B[j - 1]
            elif j == 0:
                max_left = A[i - 1]
            else:
                max_left = max(A[i - 1], B[j - 1])
            if (m + n) % 2 == 1:
                return float(max_left)
            if i == m:
                min_right = B[j]
            elif j == n:
                min_right = A[i]
            else:
                min_right = min(A[i], B[j])
            return (max_left + min_right) / 2.0
    return 0.0

