// ListNode 由评测环境提供，请勿重复定义
class Solution {
public:
    ListNode* swapPairs(ListNode* head) {
        // ① 算法核心思路：哑节点加三指针，每轮交换相邻两个节点后前移一对
        // ② 关键步骤与易错点：按 a->next = b->next、b->next = a、prev->next = b 的顺序调整指针
        // ③ 时间复杂度 O(n)，空间复杂度 O(1)
        // 哑节点 + 三指针：prev -> a -> b，交换 a、b 后移动 prev
        ListNode dummy(0);
        dummy.next = head;
        ListNode* prev = &dummy;
        while (prev->next && prev->next->next) {
            ListNode* a = prev->next;
            ListNode* b = a->next;
            a->next = b->next;
            b->next = a;
            prev->next = b;
            prev = a;
        }
        return dummy.next;
    }
};

