def firstMissingPositive(nums):
    # 核心思路：利用数组本身做原地哈希，把值 x（1<=x<=n）放到下标 x-1 处，
    # 使每个位置满足 nums[i] == i+1，从而可按下标判断缺失的最小正整数。
    # 关键步骤：交换用 while 循环反复进行，目标位置已就位或值越界时停止；
    # 最后扫描第一个 nums[i] != i+1 的位置即为答案，全部就位则答案是 n+1。
    # 复杂度：时间 O(n)，空间 O(1)。
    n = len(nums)
    for i in range(n):
