class Solution {
    // 核心思路：回溯逐行放置皇后，用列、两条对角线的占用标记剪枝。
    // 关键点：d1[r+c] 与 d2[r-c+n-1] 分别对应两条对角线方向。
    // 易错点：递归返回后需撤销标记并还原棋盘。
    // 时间复杂度 O(n!)，空间复杂度 O(n)。
public:
    vector<vector<string>> solveNQueens(int n) {
        vector<string> board(n, string(n, '.'));
        vector<bool> cols(n, false), d1(2 * n - 1, false), d2(2 * n - 1, false);
        vector<vector<string>> res;
        function<void(int)> dfs = [&](int r) {
            if (r == n) {
                res.push_back(board);
                return;
            }
            for (int c = 0; c < n; c++) {
                if (cols[c] || d1[r + c] || d2[r - c + n - 1]) continue;
                cols[c] = d1[r + c] = d2[r - c + n - 1] = true;
                board[r][c] = 'Q';
                dfs(r + 1);
                board[r][c] = '.';
                cols[c] = d1[r + c] = d2[r - c + n - 1] = false;
            }
        };
        dfs(0);
        return res;
    }
};

