class Solution {
public:
    vector<int> spiralOrder(vector<vector<int>>& matrix) {
        // 核心思路：用半开区间 [left,right) x [top,bottom) 表示尚未遍历的区域，
        // 按上、右、下、左四条边逐圈读取元素并逐步收缩边界。
        // 关键步骤：每圈走完上、右两边后检查区域是否仍有效再走下面两边，
        // 否则单行或单列场景会重复读取元素。
        // 复杂度：时间 O(mn)，空间 O(1)（不计返回数组）。
        vector<int> res;
        int m = (int)matrix.size(), n = (int)matrix[0].size();
        int left = 0, right = n, top = 0, bottom = m;
        while (left < right && top < bottom) {
            for (int i = left; i < right; i++) res.push_back(matrix[top][i]);
            top++;
            for (int i = top; i < bottom; i++) res.push_back(matrix[i][right - 1]);
            right--;
            if (!(left < right && top < bottom)) break;
            for (int i = right - 1; i >= left; i--) res.push_back(matrix[bottom - 1][i]);
            bottom--;
            for (int i = bottom - 1; i >= top; i--) res.push_back(matrix[i][left]);
            left++;
        }
        return res;
    }
};

