    // 关键步骤：每圈走完上、右两边后检查区域是否仍有效再走下面两边，
    // 否则单行或单列场景会重复读取元素。
    // 复杂度：时间 O(mn)，空间 O(1)（不计返回数组）。
    vector<int> res;
    int left = 0, right = n, top = 0, bottom = m;
    while (left < right && top < bottom) {
        for (int i = left; i < right; i++) res.push_back(mat[top][i]);
        top++;
        for (int i = top; i < bottom; i++) res.push_back(mat[i][right - 1]);
        right--;
        if (!(left < right && top < bottom)) break;
        for (int i = right - 1; i >= left; i--) res.push_back(mat[bottom - 1][i]);
        bottom--;
        for (int i = bottom - 1; i >= top; i--) res.push_back(mat[i][left]);
        left++;
    }
    for (size_t i = 0; i < res.size(); i++) {
        if (i) cout << ' ';
        cout << res[i];
    }
    cout << '\n';
    return 0;
}

