def canJump(nums):
    # 算法思路: 贪心。reach 记录当前能到达的最远下标, 逐格向前推进。
    # 关键点: 一旦某个下标超过 reach, 说明中间已断开, 无法到达终点。
    # 时间复杂度 O(n), 空间复杂度 O(1)。
    reach = 0
    for i, v in enumerate(nums):
        if i > reach:
            return False
        reach = max(reach, i + v)
    return True

