def sortColors(nums):
    # 算法思路：荷兰国旗问题，用三指针原地对 0、1、2 排序
    # i 指向 0 区域的右边界，k 指向 2 区域的左边界，j 为当前扫描指针
    # 易错点：与 2 交换后 j 不前进，因为换来的元素还需判断；与 0 交换后 i、j 同时前进
    # 时间复杂度 O(n)，空间复杂度 O(1)
    i, j, k = 0, 0, len(nums) - 1
    while j <= k:
        if nums[j] == 0:
            nums[i], nums[j] = nums[j], nums[i]  # 换到 0 区域
            i += 1
            j += 1
        elif nums[j] == 2:
            nums[j], nums[k] = nums[k], nums[j]  # 换到 2 区域，j 不前进
            k -= 1
        else:
            j += 1  # 是 1，直接跳过

