class Solution {
public:
    string minWindow(string s, string t) {
        // 核心思路：滑动窗口加计数。need 记录 t 中每个字符的需求次数，
        // formed 统计当前窗口内已满足出现次数的字符种类数。
        // 关键步骤：右指针扩张窗口直至 formed 达标，再收缩左指针寻找更短
        // 覆盖子串并更新最优解；移动左指针时同步回退计数。
        // 复杂度：时间 O(len(s)+len(t))，空间 O(|字符集|)。
        if (t.empty()) return "";
        unordered_map<char, int> need, have;
        for (char c : t) need[c]++;
        int formed = 0, required = (int)need.size();
        int left = 0, bestL = -1, bestLen = INT_MAX;
        for (int right = 0; right < (int)s.size(); right++) {
            char c = s[right];
            have[c]++;
            if (need.count(c) && have[c] == need[c]) formed++;
            while (formed == required && left <= right) {
                if (right - left + 1 < bestLen) {
                    bestLen = right - left + 1;
                    bestL = left;
                }
                char lc = s[left];
                have[lc]--;
                if (need.count(lc) && have[lc] < need[lc]) formed--;
                left++;
            }
        }
        return bestL == -1 ? "" : s.substr(bestL, bestLen);
    }
};

