class Solution {
public:
    bool exist(vector<vector<char>>& board, string word) {
        // 核心思路: 回溯搜索，从任意格子出发沿四个方向逐字符匹配 word。
        // 关键步骤: 越界或字符不匹配立即返回 false，匹配完最后一个字符即成功。
        // 易错点: 访问过的格子要标记为 #，回溯后必须恢复原字符。
        // 复杂度: 时间 O(m·n·3^k)，空间 O(k) 递归栈，k 为单词长度。
        int m = board.size(), n = board[0].size();
        int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        function<bool(int, int, int)> dfs = [&](int i, int j, int k) -> bool {
            if (i < 0 || i >= m || j < 0 || j >= n || board[i][j] != word[k]) return false;
            if (k == (int)word.size() - 1) return true;
            board[i][j] = '#';          // 标记已访问
            for (auto& d : dirs)
                if (dfs(i + d[0], j + d[1], k + 1)) return true;
            board[i][j] = word[k];      // 回溯恢复
            return false;
        };
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (dfs(i, j, 0)) return true;
        return false;
    }
};

