// 思路：递归深度优先遍历，按左子树、根、右子树的顺序收集节点值。
// 易错点：空节点直接返回；左根右的访问顺序不能颠倒。
// 复杂度：时间 O(n)，空间 O(n)（递归栈与结果数组）。
class Solution {
public:
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> out;
        function<void(TreeNode*)> dfs = [&](TreeNode* node) {
            if (!node) return;
            dfs(node->left);
            out.push_back(node->val);
            dfs(node->right);
        };
        dfs(root);
        return out;
    }
};

