    # 关键:左子树递归时上界收紧为 node.val,右子树递归时下界收紧为 node.val
    # 易错:上下界用正负无穷初始化,避免 int 边界值误判
    # 复杂度:时间 O(n),空间 O(h),h 为树高
    def check(node, lo, hi):
        if not node:
            return True
        if not (lo < node.val < hi):
            return False
        return check(node.left, lo, node.val) and check(node.right, node.val, hi)  # 左子树收紧上界,右子树收紧下界
    return check(root, float('-inf'), float('inf'))

