def maxProfit(prices):
    # 算法思路: 一次遍历。维护历史最低买入价 min_price, 每天计算当天卖出可得的收益。
    # 关键点: 先更新最低价再比较收益, 保证卖出日不早于买入日。
    # 时间复杂度 O(n), 空间复杂度 O(1)。
    min_price = float('inf')
    ans = 0
    for p in prices:
        if p < min_price:
            min_price = p
        elif p - min_price > ans:
            ans = p - min_price
    return ans

