class Solution {
public:
    int longestConsecutive(vector<int>& nums) {
        // 核心思路：哈希集合去重，支持 O(1) 判断相邻数是否存在
        // 仅从每个连续序列的最小值开始向后延伸统计
        // 时间复杂度 O(n)，空间复杂度 O(n)
        unordered_set<int> s(nums.begin(), nums.end());
        int best = 0;
        for (int x : s) {
            if (s.count(x - 1)) continue;
            int cur = x, len = 1;
            while (s.count(cur + 1)) { cur++; len++; }
            best = max(best, len);
        }
        return best;
    }
};

