def partition(s):
    # 核心思路：回溯 DFS 枚举分割点，要求每个片段都是回文串。
    # 关键点：is_pal 用双指针判断子串回文；分割点 end 从 start 枚举到末尾。
    # 易错点：递归前先加入 path，递归后必须 pop 恢复现场。
    # 时间复杂度 O(n * 2^n)，空间复杂度 O(n)。
    n = len(s)
    res = []

    def is_pal(i, j):
        while i < j:
            if s[i] != s[j]:
                return False
            i += 1
            j -= 1
        return True

    def dfs(start, path):
        if start == n:
            res.append(path[:])
            return
        for end in range(start, n):
            if is_pal(start, end):
                path.append(s[start:end + 1])
                dfs(end + 1, path)
                path.pop()

    dfs(0, [])
    return res

