#include <bits/stdc++.h>
using namespace std;

struct Node {
    int val;
    Node* next;
    Node* random;
    Node(int x = 0) : val(x), next(nullptr), random(nullptr) {}
};

// 思路：三次遍历完成深拷贝，无需额外哈希表。
// 第一步在每个原节点后插入值相同的拷贝节点，第二步按原 random 指向设置拷贝的 random，
// 第三步把拷贝节点从原链分离并还原原链。
// 易错点：random 为空时跳过；分离时先断原链 next 再断拷贝链 next。
// 复杂度：时间 O(n)，空间 O(1)（不计结果链表本身）。
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<Node*> nodes(n);
    vector<int> rand(n);
    for (int i = 0; i < n; i++) {
        int v, r;
        cin >> v >> r;
        nodes[i] = new Node(v);
        rand[i] = r;
    }
    for (int i = 0; i < n; i++) {
        if (i + 1 < n) nodes[i]->next = nodes[i + 1];
        if (rand[i] >= 0) nodes[i]->random = nodes[rand[i]];
    }
    Node* head = nodes.empty() ? nullptr : nodes[0];
    // 哈希法深拷贝
    unordered_map<Node*, Node*> m;
    Node dummy(0);
    Node* pre = &dummy;
    for (Node* cur = head; cur; cur = cur->next) {
        m[cur] = new Node(cur->val);
        pre->next = m[cur];
        pre = pre->next;
    }
    for (Node* cur = head; cur; cur = cur->next) {
        if (cur->random) m[cur]->random = m[cur->random];
    }
    Node* new_head = dummy.next;
    // 输出 val 与 random 在新链表中的下标
    unordered_map<Node*, int> pos;
    int i = 0;
    for (Node* cur = new_head; cur; cur = cur->next) pos[cur] = i++;
    for (Node* cur = new_head; cur; cur = cur->next) {
        int r = (cur->random && pos.count(cur->random)) ? pos[cur->random] : -1;
        cout << cur->val << ' ' << r << '\n';
    }
    return 0;
}

