# 思路：哈希表保证 O(1) 查找，键的插入顺序即访问的新旧顺序。
# get 时先删除再重新插入该键以刷新为最新；put 更新或新增后检查容量。
# 易错点：超出容量时弹出最早插入的键，即迭代遇到的第一个键。
# 复杂度：get 与 put 均摊 O(1)，空间 O(capacity)。
class LRUCache:
    def __init__(self, capacity: int):
        self.cap = capacity
        self.d = {}

    def get(self, key: int) -> int:
        if key not in self.d:
            return -1
        # 删除后重新插入，使其成为最新使用
        v = self.d.pop(key)
        self.d[key] = v
        return v

    def put(self, key: int, value: int) -> None:
        if key in self.d:
            self.d.pop(key)
        self.d[key] = value
        if len(self.d) > self.cap:
            # 弹出最先插入（最久未使用）的键
            self.d.pop(next(iter(self.d)))

