// 思路：哈希表保证 O(1) 查找，键的插入顺序即访问的新旧顺序。
// get 时先删除再重新插入该键以刷新为最新；put 更新或新增后检查容量。
// 易错点：超出容量时弹出最早插入的键，即迭代遇到的第一个键。
// 复杂度：get 与 put 均摊 O(1)，空间 O(capacity)。
class LRUCache {
public:
    list<pair<int, int>> q;
    unordered_map<int, list<pair<int, int>>::iterator> m;
    int cap;

    LRUCache(int capacity) { cap = capacity; }

    int get(int key) {
        if (!m.count(key)) return -1;
        auto it = m[key];
        int v = it->second;
        q.erase(it);
        q.push_front({key, v});
        m[key] = q.begin();
        return v;
    }

    void put(int key, int value) {
        if (m.count(key)) q.erase(m[key]);
        q.push_front({key, value});
        m[key] = q.begin();
        if ((int)q.size() > cap) {
            m.erase(q.back().first);
            q.pop_back();
        }
    }
};

