class Solution {
public:
    int maxProduct(vector<int>& nums) {
        // 算法思路：动态规划。同时维护以当前元素结尾的最大乘积 cur_max 与
        // 最小乘积 cur_min，负数会反转大小关系，需要两个状态（负负得正）。
        // 关键点：遇到负数先交换两个状态再更新；每个元素可单独成子数组。
        // 易错点：中间乘积可能溢出 int，用 long long 计算后转回 int。
        // 时间复杂度 O(n)，空间复杂度 O(1)。
        long long cur_max = nums[0], cur_min = nums[0], best = nums[0];
        for (int i = 1; i < (int)nums.size(); i++) {
            long long v = nums[i];
            if (v < 0) swap(cur_max, cur_min); // 负数反转大小关系
            cur_max = max(v, cur_max * v);
            cur_min = min(v, cur_min * v);
            best = max(best, cur_max);
        }
        return (int)best;
    }
};

