// ListNode 由评测环境提供，请勿重复定义
class Solution {
public:
    ListNode* getIntersectionNode(ListNode* headA, ListNode* headB) {
        // ① 算法核心思路：pA、pB 各走完本链后换到另一条链，消除长度差后在交点相遇
        // ② 关键步骤与易错点：pA = pA ? pA->next : headB 实现换链；无交点时两者同时为 nullptr 退出
        // ③ 时间复杂度 O(lenA + lenB)，空间复杂度 O(1)
        // 双指针：各自走完本链后换到另一条链，最终在相交点相遇
        ListNode* pA = headA;
        ListNode* pB = headB;
        while (pA != pB) {
            pA = pA ? pA->next : headB;
            pB = pB ? pB->next : headA;
        }
        return pA;
    }
};

