#include <bits/stdc++.h>
using namespace std;

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x = 0) : val(x), next(nullptr) {}
};

int main() {
    // ① 算法核心思路：A、B 尾部共享；双指针各走完本链后换链，长度差被抹平后在交点相遇
    // ② 关键步骤与易错点：读入顺序为 lenA、lenB、valsA、valsB、skipA、skipB；B 先建 skipB 个前缀节点再接入共享段
    // ③ 时间复杂度 O(lenA + lenB)，空间复杂度 O(lenA)（nodesA 保存节点指针）
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int lenA, lenB;
    cin >> lenA >> lenB;
    vector<int> valsA(lenA), valsB(lenB);
    for (int i = 0; i < lenA; i++) cin >> valsA[i];
    for (int i = 0; i < lenB; i++) cin >> valsB[i];
    int skipA, skipB;
    cin >> skipA >> skipB;
    // 构建链表 A
    vector<ListNode*> nodesA;
    ListNode* headA = new ListNode();
    ListNode* cur = headA;
    for (int v : valsA) {
        cur->next = new ListNode(v);
        cur = cur->next;
        nodesA.push_back(cur);
    }
    headA = headA->next;
    // 构建链表 B：前缀 + A 的共享段
    ListNode* headB = new ListNode();
    cur = headB;
    for (int i = 0; i < skipB; i++) {
        cur->next = new ListNode(valsB[i]);
        cur = cur->next;
    }
    if (!nodesA.empty() && skipA >= 0 && skipA < (int)nodesA.size()) {
        cur->next = nodesA[skipA];
    }
    headB = headB->next;
    // 双指针找相交点
    ListNode* pA = headA;
    ListNode* pB = headB;
    while (pA != pB) {
        pA = pA ? pA->next : headB;
        pB = pB ? pB->next : headA;
    }
    bool first = true;
    while (pA) {
        if (!first) cout << ' ';
        cout << pA->val;
        first = false;
        pA = pA->next;
    }
    cout << '\n';
    return 0;
}

