def majorityElement(nums):
    # 算法思路：摩尔投票法，维护候选数 cand 与计数 cnt
    # cnt 为 0 时更新候选为当前数，与候选相同则加一，不同则减一
    # 众数出现次数超过一半，相互抵消后最终留下的候选必为众数
    # 时间复杂度 O(n)，空间复杂度 O(1)
    cand, cnt = 0, 0
    for v in nums:
        if cnt == 0:
            cand, cnt = v, 1  # 计数归零，重新指定候选
        elif v == cand:
            cnt += 1
        else:
            cnt -= 1
    return cand

