#include <bits/stdc++.h>
using namespace std;

struct TreeNode {
    int val;
    TreeNode *left, *right;
    TreeNode(int x = 0) : val(x), left(nullptr), right(nullptr) {}
};

TreeNode* build(const vector<string>& arr) {
    if (arr.empty() || arr[0] == "null") return nullptr;
    TreeNode* root = new TreeNode(stoi(arr[0]));
    queue<TreeNode*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < arr.size()) {
        TreeNode* cur = q.front();
        q.pop();
        if (i < arr.size() && arr[i] != "null") { cur->left = new TreeNode(stoi(arr[i])); q.push(cur->left); }
        i++;
        if (i < arr.size() && arr[i] != "null") { cur->right = new TreeNode(stoi(arr[i])); q.push(cur->right); }
        i++;
    }
    return root;
}

int main() {
    // 思路:BFS 层序遍历,记录每层最右节点
    // 输入:第一行 n,随后 n 个节点描述,null 表示空节点
    // 关键:每层最后一个弹出节点即右视图节点
    // 输出:右视图节点值,空格分隔
    // 复杂度:时间 O(n),空间 O(n)
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<string> arr(n);
    for (int i = 0; i < n; i++) cin >> arr[i];
    TreeNode* root = build(arr);
    if (!root) { cout << '\n'; return 0; }
    queue<TreeNode*> q;
    q.push(root);
    vector<int> out;
    while (!q.empty()) {
        int sz = (int)q.size();
        for (int i = 0; i < sz; i++) {
            TreeNode* cur = q.front(); q.pop();
            if (i == sz - 1) out.push_back(cur->val);
            if (cur->left) q.push(cur->left);
            if (cur->right) q.push(cur->right);
        }
    }
    for (size_t i = 0; i < out.size(); i++) {
        if (i) cout << ' ';
        cout << out[i];
    }
    cout << '\n';
    return 0;
}

