class Solution {
public:
    ListNode* reverseList(ListNode* head) {
        // ① 算法核心思路：prev、head、nxt 三指针迭代，逐个反转 next 指向
        // ② 关键步骤与易错点：先保存 nxt = head->next 再修改指向；空链表时 prev 为 nullptr 直接返回
        // ③ 时间复杂度 O(n)，空间复杂度 O(1)
        // 三指针迭代：prev / cur / nxt，逐个反转 next 指向
        ListNode* prev = nullptr;
        while (head) {
            ListNode* nxt = head->next;
            head->next = prev;
            prev = head;
            head = nxt;
        }
        return prev;
    }
};

