class Trie:
    # 核心思路: 字典树，节点用字典存子节点，并用 is_end 标记单词结尾。
    # 关键步骤: insert 沿路径建节点，search 要求走到结尾且 is_end 为真。
    # 易错点: startsWith 不检查 is_end，只要求前缀路径存在。
    # 复杂度: 三个操作均为 O(L)，L 为单词长度，空间 O(总字符数)。
    def __init__(self):
        self.children = {}
        self.is_end = False

