#include <bits/stdc++.h>
using namespace std;

struct TreeNode {
    int val;
    TreeNode *left, *right;
    TreeNode(int x = 0) : val(x), left(nullptr), right(nullptr) {}
};

TreeNode* build(const vector<string>& arr) {
    if (arr.empty() || arr[0] == "null") return nullptr;
    TreeNode* root = new TreeNode(stoi(arr[0]));
    queue<TreeNode*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < arr.size()) {
        TreeNode* cur = q.front();
        q.pop();
        if (i < arr.size() && arr[i] != "null") { cur->left = new TreeNode(stoi(arr[i])); q.push(cur->left); }
        i++;
        if (i < arr.size() && arr[i] != "null") { cur->right = new TreeNode(stoi(arr[i])); q.push(cur->right); }
        i++;
    }
    return root;
}

// 思路：自顶向下递归，先交换当前节点的左右子树，再递归处理左右子树。
// 易错点：空节点直接返回，交换与递归的顺序不影响结果。
// 复杂度：时间 O(n)，空间 O(h)，h 为树高（递归栈深度）。
TreeNode* invertTree(TreeNode* root) {
    if (!root) return nullptr;
    swap(root->left, root->right);
    invertTree(root->left);
    invertTree(root->right);
    return root;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<string> arr(n);
    for (int i = 0; i < n; i++) cin >> arr[i];
    TreeNode* root = invertTree(build(arr));
    // 层序输出，空节点记 null，末尾的 null 省略
    vector<string> out;
    queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        TreeNode* cur = q.front();
        q.pop();
        if (!cur) { out.push_back("null"); continue; }
        out.push_back(to_string(cur->val));
        q.push(cur->left);
        q.push(cur->right);
    }
    while (!out.empty() && out.back() == "null") out.pop_back();
    for (size_t i = 0; i < out.size(); i++) {
        if (i) cout << ' ';
        cout << out[i];
    }
    cout << '\n';
    return 0;
}

