#include <bits/stdc++.h>
using namespace std;

struct TreeNode {
    int val;
    TreeNode *left, *right;
    TreeNode(int x = 0) : val(x), left(nullptr), right(nullptr) {}
};

TreeNode* build(const vector<string>& arr) {
    if (arr.empty() || arr[0] == "null") return nullptr;
    TreeNode* root = new TreeNode(stoi(arr[0]));
    queue<TreeNode*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < arr.size()) {
        TreeNode* cur = q.front();
        q.pop();
        if (i < arr.size() && arr[i] != "null") { cur->left = new TreeNode(stoi(arr[i])); q.push(cur->left); }
        i++;
        if (i < arr.size() && arr[i] != "null") { cur->right = new TreeNode(stoi(arr[i])); q.push(cur->right); }
        i++;
    }
    return root;
}

int main() {
    // 思路:后序遍历分别查找 p 与 q,取汇聚节点
    // 输入:第一行 n,随后 n 个节点描述,再两个目标值 p 与 q
    // 关键:左右子树都命中时当前节点为最近公共祖先
    // 输出:最近公共祖先的节点值并换行
    // 复杂度:时间 O(n),空间 O(h)
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<string> arr(n);
    for (int i = 0; i < n; i++) cin >> arr[i];
    int p, q;
    cin >> p >> q;
    TreeNode* root = build(arr);
    function<TreeNode*(TreeNode*)> lca = [&](TreeNode* node) -> TreeNode* {
        if (!node || node->val == p || node->val == q) return node;
        TreeNode* l = lca(node->left);
        TreeNode* r = lca(node->right);
        if (l && r) return node;
        return l ? l : r;
    };
    cout << lca(root)->val << '\n';
    return 0;
}

