def moveZeroes(nums):
    # 核心思路：双指针，j 指向下一个非零元素应落的位置
    # 遍历到非零元素就与 j 位置交换，把零逐步右移
    # 交换过程保证非零元素的相对顺序不变
    # 时间复杂度 O(n)，空间复杂度 O(1)
    j = 0
    for i in range(len(nums)):
        if nums[i] != 0:
            nums[i], nums[j] = nums[j], nums[i]
            j += 1

