class Solution {
public:
    void moveZeroes(vector<int>& nums) {
        // 核心思路：双指针，j 指向下一个非零元素应落的位置
        // 遇到非零元素就与 j 交换，零自然被推到数组尾部
        // 时间复杂度 O(n)，空间复杂度 O(1)
        int j = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            if (nums[i] != 0) {
                swap(nums[i], nums[j]);
                j++;
            }
        }
    }
};

