import sys
import heapq

class MedianFinder:
    # 算法思路: 双堆维护中位数, lo 为较小一半的大根堆, hi 为较大一半的小根堆。
    # 关键点: 保持两堆大小平衡; 奇数个元素时中位数为 lo 堆顶。
    # 时间复杂度: addNum O(log n), findMedian O(1); 空间复杂度 O(n)。
    def __init__(self):
        self.lo = []
        self.hi = []
    def addNum(self, num):
        heapq.heappush(self.lo, -num)
        heapq.heappush(self.hi, -heapq.heappop(self.lo))
        if len(self.hi) > len(self.lo):
            heapq.heappush(self.lo, -heapq.heappop(self.hi))
    def findMedian(self):
        if len(self.lo) > len(self.hi):
            return -self.lo[0]
        return (-self.lo[0] + self.hi[0]) / 2.0

def fmt(v):
    iv = int(v)
    return str(iv) if v == iv else str(v)

def main():
    # 算法思路: 按操作序列调用双堆中位数类, 将查询结果逐行收集后输出。
    # 关键点: 输出前用 fmt 规范化浮点数, 避免多余的小数位。
    # 时间复杂度: 整体 O(m log m); 空间复杂度 O(m)。
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    m = int(next(it))
    mf = MedianFinder()
    out = []
    for _ in range(m):
        op = next(it)
        if op == 'addNum':
            mf.addNum(int(next(it)))
        else:
            out.append(fmt(mf.findMedian()))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))

if __name__ == "__main__":
    main()

