class MedianFinder {
    // 算法思路: 双堆。lo 为较小一半的大根堆, hi 为较大一半的小根堆, 两堆大小差不超过 1。
    // 关键点: addNum 先入 lo 再转 hi; hi 更大时回拨一个到 lo 保持平衡。
    // 中位数为 lo 堆顶或两堆顶平均值。
    // 时间复杂度: addNum O(log n), findMedian O(1); 空间复杂度 O(n)。
public:
    priority_queue<int> lo;                     // 较小一半，大根堆
    priority_queue<int, vector<int>, greater<int>> hi;  // 较大一半，小根堆

    MedianFinder() {}

    void addNum(int num) {
        lo.push(num);
        hi.push(lo.top());
        lo.pop();
        if (hi.size() > lo.size()) {
            lo.push(hi.top());
            hi.pop();
        }
    }

    double findMedian() {
        if (lo.size() > hi.size()) return lo.top();
        return ((double)lo.top() + hi.top()) / 2.0;
    }
};

