def lengthOfLIS(nums):
    # 算法思路：贪心加二分。tails[i] 记录长度为 i+1 的递增子序列的最小末尾值，
    # tails 保持严格单调递增，便于二分定位。
    # 关键点：二分找第一个不小于 x 的位置，用 x 覆盖它使末尾值尽可能小；
    # 若 x 大于所有末尾值则追加到尾部，此时最长长度加一。
    # 时间复杂度 O(n log n)，空间复杂度 O(n)。
    tails = []
    for x in nums:
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < x:
                lo = mid + 1
            else:
                hi = mid
