import sys

def main():
    # 算法思路：贪心加二分。tails[i] 记录长度为 i+1 的递增子序列的最小末尾值，
    # tails 严格单调递增，可二分查找插入位置。
    # 关键点：用 x 覆盖第一个不小于 x 的位置，使末尾值尽量小；
    # 找不到则追加到尾部，最长长度加一。
    # 时间复杂度 O(n log n)，空间复杂度 O(n)。
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    tails = []
    for x in nums:
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(x)
        else:
            tails[lo] = x
    print(len(tails))

if __name__ == "__main__":
    main()

