def decodeString(s):
    # 算法思路: 栈模拟。遇到 [ 把当前字符串与重复次数入栈, 遇到 ] 弹出并按次数拼接。
    # 关键点: 数字可能占多位, 需累加; 嵌套结构靠栈的先进后出逐层还原。
    # 时间复杂度 O(解码后字符串长度), 空间复杂度 O(解码后字符串长度)。
    stack = []          # 栈中存 (之前的字符串, 重复次数)
    cur_num = 0
    cur_str = ''
    for ch in s:
        if ch.isdigit():
            cur_num = cur_num * 10 + int(ch)   # 数字可能多位
        elif ch == '[':
            stack.append((cur_str, cur_num))
            cur_str = ''
            cur_num = 0
        elif ch == ']':
            pre, num = stack.pop()
            cur_str = pre + cur_str * num
        else:
            cur_str += ch
    return cur_str

