class Solution {
public:
    // 算法思路: 栈模拟解码。遇到 [ 把当前字符串与次数压栈, 遇到 ] 弹出并按次数拼接。
    // 关键点: 数字可能多位需累加; 嵌套结构靠栈的先进后出还原。
    // 时间复杂度 O(解码后字符串长度), 空间复杂度 O(解码后字符串长度)。
    string decodeString(string s) {
        stack<pair<string, int>> st;   // (之前的字符串, 重复次数)
        string cur;
        int num = 0;
        for (char ch : s) {
            if (isdigit(ch)) num = num * 10 + (ch - '0');  // 数字可能多位
            else if (ch == '[') { st.push({cur, num}); cur.clear(); num = 0; }
            else if (ch == ']') {
                auto pre = st.top(); st.pop();
                string tmp = cur;
                for (int i = 1; i < pre.second; i++) cur += tmp;
                cur = pre.first + cur;
            } else cur += ch;
        }
        return cur;
    }
};

