class Solution {
public:
    vector<int> findAnagrams(string s, string p) {
        // 核心思路：定长滑动窗口加 26 长度计数数组
        // need 为 p 的字符频次，win 为窗口内的字符频次
        // 窗口右端进一个字符、左端出一个字符，保持长度不变
        // 频次完全相等时记录窗口起点下标
        // 时间复杂度 O(n)，空间复杂度 O(1)
        if (s.size() < p.size()) return {};
        vector<int> need(26, 0), win(26, 0);
        for (char c : p) need[c - 'a']++;
        int m = (int)p.size();
        vector<int> res;
        for (int i = 0; i < (int)s.size(); i++) {
            win[s[i] - 'a']++;
            if (i >= m) win[s[i - m] - 'a']--;
            if (i >= m - 1 && win == need) res.push_back(i - m + 1);
        }
        return res;
    }
};

