    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<string> arr(n);
    for (int i = 0; i < n; i++) cin >> arr[i];
    best = 0;
    depth(build(arr));
    cout << best << '\n';
    return 0;
}

