public:
    int subarraySum(vector<int>& nums, int k) {
        // 核心思路：前缀和加哈希表统计出现次数
        // 子数组和为 k 当且仅当 pre - k 在前面出现过
        // 先累加答案再更新当前前缀和计数
        // 用 long long 存储前缀和防止溢出
        // 时间复杂度 O(n)，空间复杂度 O(n)
        unordered_map<long long, int> cnt;
        cnt[0] = 1;
        long long pre = 0;
        int ans = 0;
        for (int x : nums) {
            pre += x;
            ans += cnt[pre - k];
            cnt[pre]++;
        }
        return ans;
    }
};

