class Solution {
public:
    // 算法思路: 单调栈。从右向左遍历, 栈存下标且温度严格递减。
    // 关键点: 弹出所有不大于当前温度的下标, 栈顶即右侧第一个更高温度的位置。
    // 时间复杂度 O(n), 空间复杂度 O(n)。
    vector<int> dailyTemperatures(vector<int>& temperatures) {
        int n = temperatures.size();
        vector<int> ans(n, 0);
        stack<int> st;                 // 单调递减栈，存下标
        for (int i = n - 1; i >= 0; i--) {
            while (!st.empty() && temperatures[st.top()] <= temperatures[i]) st.pop();
            if (!st.empty()) ans[i] = st.top() - i;
            st.push(i);
        }
        return ans;
    }
};

