def partitionLabels(s):
    # 算法思路: 贪心。先记录每个字符最后一次出现的下标, 扫描时不断扩展当前段的右边界。
    # 关键点: 当 i 到达 end 时说明段内字符不再出现, 记录长度并开启新段。
    # 时间复杂度 O(n), 空间复杂度 O(1) (字符集固定为 26)。
    last = {}
    for i, ch in enumerate(s):
        last[ch] = i
    ans = []
    start = end = 0
    for i, ch in enumerate(s):
        end = max(end, last[ch])
        if i == end:
            ans.append(end - start + 1)
            start = i + 1
    return ans

